import { Controller, HttpCode, Patch, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 시각 문자열 형식 검사 (날짜 해석은 DB가 한다)
const TIMESTAMP_FORMAT = /^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?(Z|[+-][0-9]{2}(:?[0-9]{2})?)?$/;
// 가정: 마감 상태 값 '마감'인 근태만 조정을 거절한다 (마감취소 후에만 조정 가능)
const CLOSED_STATUS = '마감';
// 가정: 수기 조정 기록 출처
const MANUAL_SOURCE = 'MANUAL';

function optionalTimestamp(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || !TIMESTAMP_FORMAT.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01805Controller {
  @Patch('/attendance-dailies/:attendanceDailyId')
  async adjustAttendanceDaily(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자', '근태 담당자');
    const data = checks.inputOf(req.body);
    const idText = req.params['attendanceDailyId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '일별 근태 기록 ID가 올바르지 않습니다.');
    }
    const clockInAt = optionalTimestamp(data['clockInAt'], '출근시각');
    const clockOutAt = optionalTimestamp(data['clockOutAt'], '퇴근시각');
    if (clockInAt === null && clockOutAt === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '출근시각 또는 퇴근시각을 입력하세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT closing_status AS "closingStatus" FROM attendance_daily WHERE attendance_daily_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_DAILY_NOT_FOUND', '대상 근태를 찾을 수 없습니다.');
      }
      if (found[0]['closingStatus'] === CLOSED_STATUS) {
        throw new ApiError(409, 'ATTENDANCE_CLOSED', '마감된 근태는 마감취소 후에만 조정할 수 있습니다.');
      }
      const order = await db.query(
        'SELECT (COALESCE(CAST(:clockInAt AS timestamptz), clock_in_at) <= COALESCE(CAST(:clockOutAt AS timestamptz), clock_out_at)) AS "ok" FROM attendance_daily WHERE attendance_daily_id = CAST(:id AS bigint)',
        { id: idText, clockInAt, clockOutAt },
      );
      if (order[0]['ok'] === false) {
        throw new ApiError(400, 'VALIDATION_FAILED', '퇴근시각은 출근시각보다 빠를 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE attendance_daily SET clock_in_at = COALESCE(CAST(:clockInAt AS timestamptz), clock_in_at), clock_out_at = COALESCE(CAST(:clockOutAt AS timestamptz), clock_out_at), source_type = :sourceType, updated_at = now() WHERE attendance_daily_id = CAST(:id AS bigint) RETURNING attendance_daily_id AS "attendanceDailyId"',
        { id: idText, clockInAt, clockOutAt, sourceType: MANUAL_SOURCE },
      );
      return rows[0];
    });
  }
}

