import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Pager,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr01805Page({ role, notify }: PageProps) {
  const [area, setArea] = useState('');
  const [appliedArea, setAppliedArea] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [editing, setEditing] = useState<Row | null>(null);
  const [settingValue, setSettingValue] = useState('');
  const [appliedFrom, setAppliedFrom] = useState('');
  const [adjusting, setAdjusting] = useState(false);
  const [dailyId, setDailyId] = useState<number | string>('');
  const [clockInAt, setClockInAt] = useState('');
  const [clockOutAt, setClockOutAt] = useState('');
  const [adjusted, setAdjusted] = useState<Row[]>([]);

  const list = useData<Page>(
    () => call<Page>('GET', '/config-settings', role, undefined, { settingArea: appliedArea, page: pageNo, size: SIZE }),
    [appliedArea, pageNo, role],
  );

  function openEdit(row: Row) {
    setEditing(row);
    setSettingValue(String(row['settingValue'] ?? ''));
    setAppliedFrom(String(row['appliedFrom'] ?? '').slice(0, 10));
  }

  function openAdjust() {
    setDailyId('');
    setClockInAt('');
    setClockOutAt('');
    setAdjusting(true);
  }

  async function saveSetting() {
    if (!editing) {
      return;
    }
    if (!settingValue.trim() || !appliedFrom) {
      throw new Error('설정 값과 적용 시작일을 입력하세요.');
    }
    await call('PUT', '/config-settings/' + String(editing['configSettingId']), role, { settingValue, appliedFrom });
    notify('설정을 저장했습니다.');
    setEditing(null);
    list.reload();
  }

  async function saveAdjust() {
    if (dailyId === '') {
      throw new Error('조정할 근태를 선택하세요.');
    }
    if (!clockInAt.trim() && !clockOutAt.trim()) {
      throw new Error('출근시각 또는 퇴근시각을 입력하세요.');
    }
    const body: Row = {};
    if (clockInAt.trim()) {
      body['clockInAt'] = clockInAt.trim();
    }
    if (clockOutAt.trim()) {
      body['clockOutAt'] = clockOutAt.trim();
    }
    const result = await call('PATCH', '/attendance-dailies/' + String(dailyId), role, body);
    notify('근태를 조정했습니다.');
    setAdjusted([{ ...result, clockInAt: body['clockInAt'], clockOutAt: body['clockOutAt'] }, ...adjusted]);
    setAdjusting(false);
  }

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  return (
    <div className={'bento'}>
      <section className={'box span-12'}>
        <h2>{'현황'}</h2>
        <Tiles items={[['설정 항목', total], ['이번 조정 건수', adjusted.length]]} />
      </section>
      <section className={'box span-8'}>
        <h2>{'근태 설정'}</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setAppliedArea(area);
          }}
          onReset={() => {
            setArea('');
            setAppliedArea('');
            setPageNo(0);
          }}
        >
          <Field label={'설정 영역'}>
            <TextInput value={area} onChange={setArea} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type={'button'} onClick={openAdjust}>{'특정일 근태 조정'}</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          columns={[
            { key: 'settingArea', label: '설정 영역' },
            { key: 'settingKey', label: '설정 키' },
            { key: 'settingValue', label: '설정 값' },
            { key: 'appliedFrom', label: '적용 시작일', render: (r: Row) => <DateText value={r['appliedFrom']} /> },
            {
              key: 'configSettingId',
              label: '처리',
              render: (r: Row) => (
                <button type={'button'} onClick={() => openEdit(r)}>{'수정'}</button>
              ),
            },
          ]}
          rows={rows}
          empty={'설정이 없습니다.'}
        />
        <Pager page={pageNo} size={SIZE} total={total} onPage={setPageNo} />
      </section>
      <section className={'box span-4'}>
        <h2>{'최근 조정'}</h2>
        <DataTable
          columns={[
            { key: 'attendanceDailyId', label: '일별 근태 기록' },
            { key: 'clockInAt', label: '출근시각' },
            { key: 'clockOutAt', label: '퇴근시각' },
            { key: 'result', label: '결과', render: () => <Badge value={'완료'} /> },
          ]}
          rows={adjusted}
          empty={'조정 내역이 없습니다.'}
        />
      </section>
      {editing ? (
        <Drawer title={'설정 수정'} onClose={() => setEditing(null)}>
          <Form onSubmit={saveSetting} submit={'저장'} note={'변경은 적용 시작일 이후 처리 건부터 적용됩니다.'}>
            <Field label={'설정 키'}>
              <span>{String(editing['settingKey'] ?? '')}</span>
            </Field>
            <Field label={'설정 값'} required wide>
              <TextInput value={settingValue} onChange={setSettingValue} />
            </Field>
            <Field label={'적용 시작일'} required>
              <DateInput value={appliedFrom} onChange={setAppliedFrom} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {adjusting ? (
        <Drawer title={'특정일 근태 조정'} onClose={() => setAdjusting(false)}>
          <Form onSubmit={saveAdjust} submit={'조정'} note={'마감된 근태는 마감취소 후에만 조정할 수 있습니다.'}>
            <Field label={'일별 근태 기록'} required wide>
              <LookupSelect table={'attendance_daily'} role={role} value={dailyId} onChange={setDailyId} />
            </Field>
            <Field label={'출근시각'} hint={'예: 2025-01-02T09:00:00+09:00'}>
              <TextInput value={clockInAt} onChange={setClockInAt} />
            </Field>
            <Field label={'퇴근시각'} hint={'예: 2025-01-02T18:00:00+09:00'}>
              <TextInput value={clockOutAt} onChange={setClockOutAt} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
